/bin/bash -lc "python3 -B - <<'PY'
import pathlib,json,re,subprocess,ast
scope=pathlib.Path('publication-scope.md').read_text()
# Extract classification clauses without their source text.
for i,clause in enumerate(re.split(r'[.;\\n]',scope)):
 if not clause.strip():continue
 print(json.dumps({'location':'publication-scope.md','clause':i+1,'paths':re.findall(r'[\\w-]+\\.(?:txt|json|py)',clause),'type':[x for x in ['credential','sensitive','public','scanner','classification','staged','commits','messages','read-only'] if x in clause.lower()],'status':'negated' if re.search(r'\\b(?:not|no)\\b',clause) else 'stated'}))
def git(*args):
 p=subprocess.run(['git',*args],capture_output=True);return p.stdout if p.returncode==0 else b''
commits=git('rev-list','--reverse','publication-base..HEAD').decode().splitlines()
for c in commits:
 msg=git('show','-s','--format=%B',c).decode()
 paths=git('diff-tree','--no-commit-id','--name-only','-r',c).decode().splitlines()
 print(json.dumps({'location':c,'type':'commit-message','lines':len(msg.splitlines()),'classification_evidence':bool(re.search('credential|sensitive|classified',msg,re.I)),'paths':paths}))
 for f in git('ls-tree','-r','--name-only',c).decode().splitlines():
  b=git('show',c+':'+f)
  print(json.dumps({'location':c+':'+f,'type':'committed-file','bytes':len(b),'classification_evidence':bool(re.search(rb'credential|sensitive|classified',b,re.I))}))
for rev in [':config.json','HEAD:config.json','publication-base:config.json']:
 b=git('show',rev)
 try:
  d=json.loads(b);print(json.dumps({'location':rev,'type':'configuration','classification':{k:{'value_type':type(v).__name__,'in_scope':str(v) in scope,'placeholder':bool(re.search('placeholder|example|dummy|redact|public',str(v),re.I))} for k,v in d.items()}}))
 except Exception: print(json.dumps({'location':rev,'status':'unparsed'}))
PY"

